const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point([-5.98, 37.38]); // A point near Seville, Southern Iberian Peninsula (agricultural area)

  // 2023 period
  const date2023_start = '2023-03-25';
  const date2023_end = '2023-04-23';

  // Long-term average period (2000-2010), same seasonal window
  const year_longterm_start = 2000;
  const year_longterm_end = 2010;
  const month_day_start = '03-25'; // March 25
  const month_day_end = '04-23';   // April 23

  const scale = 1000; // Use a reasonable scale to avoid memory issues

  // Function to mask clouds for Sentinel-2 (SR)
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select('B.*') // Select all B bands to get reflectance
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDVI for Sentinel-2
  function addS2Ndviband(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Function to mask clouds for Landsat (SR)
  function maskL57clouds(image) {
    const qa = image.select('pixel_qa');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask)
      .select(['B1', 'B2', 'B3', 'B4', 'B5', 'B7'], // Select SR bands only
              ['B2', 'B3', 'B4', 'B5', 'B6', 'B7']) // Rename to match S2-like structure if needed, but not for NDVI
      .divide(10000) // Convert to reflectance
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDVI for Landsat 5/7
  function addL57Ndviband(image) {
    const ndvi = image.normalizedDifference(['B4', 'B3']).rename('NDVI'); // B4=NIR, B3=RED for Landsat 5/7
    return image.addBands(ndvi);
  }

  // --- Process 2023 data (Sentinel-2) ---
  let s2_collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(date2023_start, date2023_end)
    .filterBounds(geometry)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 60)) // Pre-filter based on metadata
    .map(maskS2clouds)
    .map(addS2Ndviband)
    .select('NDVI');

  let s2_size = await s2_collection.size().getInfo();
  console.log(`2023 S2 Images: ${s2_size}`);

  if (s2_size === 0) {
    console.log("No Sentinel-2 images found for 2023 period.");
    console.log("C1");
    return;
  }

  let s2_ndvi_2023 = s2_collection.median();

  let s2_count = await s2_ndvi_2023.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (s2_count === 0) {
    console.log("No valid pixels for 2023 after cloud masking.");
    console.log("C2");
    return;
  }

  let s2_mean_ndvi_2023 = await s2_ndvi_2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (s2_mean_ndvi_2023 === null || isNaN(s2_mean_ndvi_2023)) {
    console.log("2023 NDVI calculation failed.");
    console.log("C3");
    return;
  }
  console.log(`2023 NDVI (mean): ${s2_mean_ndvi_2023.toFixed(3)} (Pixels: ${s2_count})`);

  // --- Process long-term average data (Landsat 5/7) ---
  let yearly_ndvi_list = ee.List([]);

  for (let year = year_longterm_start; year <= year_longterm_end; year++) {
    const year_start_date = ee.Date.fromYMD(year, 1, 1).format('yyyy').cat(ee.String('-')).cat(ee.String(month_day_start));
    const year_end_date = ee.Date.fromYMD(year, 1, 1).format('yyyy').cat(ee.String('-')).cat(ee.String(month_day_end));

    let ls_collection = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR') // Using Landsat 5 Surface Reflectance
      .filterDate(year_start_date, year_end_date)
      .filterBounds(geometry)
      .filter(ee.Filter.lt('CLOUD_COVER', 60))
      .map(maskL57clouds)
      .map(addL57Ndviband)
      .select('NDVI');

    let ls_size_year = await ls_collection.size().getInfo();
    console.log(`  Year ${year} L5 Images: ${ls_size_year}`);

    if (ls_size_year > 0) {
      let ls_ndvi_year = ls_collection.median();
      let ls_count_year = await ls_ndvi_year.select('NDVI').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('NDVI').getInfo();

      if (ls_count_year > 0) {
        let ls_mean_ndvi_year = await ls_ndvi_year.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geometry,
          scale: scale,
          maxPixels: 1e9
        }).get('NDVI').getInfo();
        if (ls_mean_ndvi_year !== null && !isNaN(ls_mean_ndvi_year)) {
          yearly_ndvi_list = yearly_ndvi_list.add(ls_mean_ndvi_year);
          console.log(`    NDVI: ${ls_mean_ndvi_year.toFixed(3)} (Pixels: ${ls_count_year})`);
        } else {
          console.log(`    Year ${year}: NDVI calculation failed (C3 for year).`);
        }
      } else {
        console.log(`    Year ${year}: No valid pixels after masking (C2 for year).`);
      }
    }
  }

  let valid_years_count = await yearly_ndvi_list.size().getInfo();
  if (valid_years_count === 0) {
    console.log("No valid Landsat images found for the long-term average period after processing.");
    console.log("C1");
    return;
  }

  let long_term_avg_ndvi = await ee.Number(yearly_ndvi_list.reduce(ee.Reducer.mean())).getInfo();

  if (long_term_avg_ndvi === null || isNaN(long_term_avg_ndvi)) {
    console.log("Long-term average NDVI calculation failed.");
    console.log("C3");
    return;
  }
  console.log(`Long-term average NDVI (${year_longterm_start}-${year_longterm_end}): ${long_term_avg_ndvi.toFixed(3)} (Valid years: ${valid_years_count})`);

  // --- Comparison and Final Answer ---
  if (s2_mean_ndvi_2023 > long_term_avg_ndvi) {
    console.log("A"); // Yes, crops were healthier
  } else {
    console.log("B"); // No, crops were not healthier or were less healthy
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
